const crypto = require('crypto');

const input = $input.first().json;

// Ajuste estes dois caminhos se no seu fluxo os nomes mudarem
const documentoId = input.id;
const documento = String(input.documento || '').trim();

// Como a RPC de iniciar indexacao nao devolve auth_user_id,
// pegamos do Webhook original do fluxo.
const authUserId =
  input.auth_user_id ||
  $('Webhook').first().json.body.auth_user_id;

if (!documentoId) {
  throw new Error('documento_id ausente para gerar chunks.');
}

if (!authUserId) {
  throw new Error('auth_user_id ausente para gerar chunks.');
}

if (!documento) {
  throw new Error('documento vazio para gerar chunks.');
}

// -----------------------------------------------------------------------------
// PARAMETROS
// -----------------------------------------------------------------------------

const TARGET_TOKENS = 400;
const MAX_TOKENS = 450;
const OVERLAP_TOKENS = 70;

// Aproximacao simples para n8n.
// Nao e um tokenizer real, mas e suficiente para manter os chunks abaixo do
// limite pratico que definimos para o text-embedding-3-small.
function estimateTokens(text) {
  const clean = String(text || '').trim();
  if (!clean) return 0;

  const words = clean.split(/\s+/).filter(Boolean).length;

  // Aproximacao conservadora:
  // em portugues, 1 palavra costuma virar um pouco mais que 1 token.
  return Math.ceil(words * 1.3);
}

function normalizeText(text) {
  return String(text || '')
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function sha256(text) {
  return crypto
    .createHash('sha256')
    .update(text, 'utf8')
    .digest('hex');
}

function splitLongTextByWords(text, maxTokens) {
  const words = text.split(/\s+/).filter(Boolean);
  const parts = [];
  let current = [];

  for (const word of words) {
    const candidate = [...current, word].join(' ');

    if (current.length > 0 && estimateTokens(candidate) > maxTokens) {
      parts.push(current.join(' '));
      current = [word];
    } else {
      current.push(word);
    }
  }

  if (current.length > 0) {
    parts.push(current.join(' '));
  }

  return parts;
}

function splitLongParagraph(paragraph, maxTokens) {
  if (estimateTokens(paragraph) <= maxTokens) {
    return [paragraph];
  }

  // Primeiro tenta quebrar por frases.
  const sentences = paragraph
    .split(/(?<=[.!?])\s+/)
    .map(s => s.trim())
    .filter(Boolean);

  if (sentences.length <= 1) {
    return splitLongTextByWords(paragraph, maxTokens);
  }

  const parts = [];
  let current = '';

  for (const sentence of sentences) {
    const candidate = current ? `${current} ${sentence}` : sentence;

    if (current && estimateTokens(candidate) > maxTokens) {
      parts.push(current);
      current = sentence;
    } else {
      current = candidate;
    }
  }

  if (current) {
    parts.push(current);
  }

  // Se alguma parte ainda ficou grande, quebra por palavras.
  return parts.flatMap(part =>
    estimateTokens(part) > maxTokens
      ? splitLongTextByWords(part, maxTokens)
      : [part]
  );
}

function getOverlapText(text, overlapTokens) {
  const words = text.split(/\s+/).filter(Boolean);

  if (words.length === 0) {
    return '';
  }

  // Estimativa inversa aproximada para converter tokens em quantidade de palavras.
  const overlapWords = Math.max(1, Math.floor(overlapTokens / 1.3));

  return words.slice(-overlapWords).join(' ');
}

// -----------------------------------------------------------------------------
// PREPARAR BLOCOS
// -----------------------------------------------------------------------------

const normalized = normalizeText(documento);

const paragraphs = normalized
  .split(/\n{2,}/)
  .map(p => p.trim())
  .filter(Boolean)
  .flatMap(p => splitLongParagraph(p, MAX_TOKENS));

// -----------------------------------------------------------------------------
// MONTAR CHUNKS
// -----------------------------------------------------------------------------

const rawChunks = [];
let currentParts = [];
let currentText = '';

for (const paragraph of paragraphs) {
  const candidate = currentText
    ? `${currentText}\n\n${paragraph}`
    : paragraph;

  if (currentText && estimateTokens(candidate) > TARGET_TOKENS) {
    rawChunks.push(currentText);

    const overlap = getOverlapText(currentText, OVERLAP_TOKENS);

    currentParts = overlap ? [overlap, paragraph] : [paragraph];
    currentText = currentParts.join('\n\n');

    // Caso overlap + novo paragrafo ainda exceda o teto, salva o overlap como apoio
    // apenas se couber; senao segue so com o novo paragrafo.
    if (estimateTokens(currentText) > MAX_TOKENS) {
      currentParts = [paragraph];
      currentText = paragraph;
    }
  } else {
    currentParts.push(paragraph);
    currentText = candidate;
  }
}

if (currentText) {
  rawChunks.push(currentText);
}

// Remove chunks vazios e qualquer chunk que, por seguranca, ainda tenha ficado grande.
const chunks = rawChunks
  .map(chunk => chunk.trim())
  .filter(Boolean)
  .flatMap(chunk =>
    estimateTokens(chunk) > MAX_TOKENS
      ? splitLongTextByWords(chunk, MAX_TOKENS)
      : [chunk]
  );

// -----------------------------------------------------------------------------
// RETORNO: 1 ITEM COM TODOS OS CHUNKS
// -----------------------------------------------------------------------------

const chunksNormalizados = chunks.map((conteudo, index) => ({
  chunk_index: index,
  conteudo,
  conteudo_hash: sha256(conteudo),
  token_count: estimateTokens(conteudo)
}));

return [
  {
    json: {
      documento_id: documentoId,
      auth_user_id: authUserId,
      qtd_chunks: chunksNormalizados.length,
      rota_indexacao: chunksNormalizados.length > 80 ? 'fila_pendentes' : 'direta',
      chunks: chunksNormalizados
    }
  }
];

// ALTERACAO OPENAI EMBEDDINGS
// A Edge Function gerar-embedding foi removida. Este node agora le o retorno direto da OpenAI.

const chunk = $('Loop Over Items - chunks pequenos').item.json;
const embeddingResponse = $json;
const embedding = embeddingResponse?.data?.[0]?.embedding;

if (!chunk) {
  throw new Error('Chunk original nao encontrado.');
}

if (!Array.isArray(embedding)) {
  throw new Error(`Embedding ausente no chunk_index ${chunk.chunk_index}.`);
}

if (embedding.length !== 384) {
  throw new Error(
    `Embedding com dimensao invalida no chunk_index ${chunk.chunk_index}: esperado 384, recebido ${embedding.length}.`
  );
}

return {
  json: {
    documento_id: chunk.documento_id,
    auth_user_id: chunk.auth_user_id,
    chunk_index: chunk.chunk_index,
    conteudo: chunk.conteudo,
    conteudo_hash: chunk.conteudo_hash,
    embedding,
    embedding_model: 'text-embedding-3-small',
    token_count: chunk.token_count,
    usage_embedding: embeddingResponse?.usage || null
  }
};

const items = $input.all();

if (items.length === 0) {
  throw new Error('Nenhum chunk indexado recebido para agrupar.');
}

const primeiroChunk = items[0].json;
const documentoId = primeiroChunk.documento_id;
const authUserId = primeiroChunk.auth_user_id;

const chunks = items.map(({ json }) => {
  if (json.documento_id !== documentoId) {
    throw new Error('Foram recebidos chunks de documentos diferentes no mesmo agrupamento.');
  }

  if (json.auth_user_id !== authUserId) {
    throw new Error('Foram recebidos chunks de usuarios diferentes no mesmo agrupamento.');
  }

  if (!Array.isArray(json.embedding)) {
    throw new Error(`Chunk ${json.chunk_index} chegou sem embedding valido.`);
  }

  return {
    chunk_index: json.chunk_index,
    conteudo: json.conteudo,
    conteudo_hash: json.conteudo_hash,
    embedding: json.embedding,
    embedding_model: json.embedding_model,
    token_count: json.token_count,
  };
});

chunks.sort((a, b) => a.chunk_index - b.chunk_index);

return [
  {
    json: {
      documento_id: documentoId,
      auth_user_id: authUserId,
      chunks,
      qtd_chunks: chunks.length,
      embedding_model: chunks[0]?.embedding_model ?? null,
    },
  },
];

const input = $input.first().json;

if (!Array.isArray(input.chunks) || input.chunks.length === 0) {
  throw new Error('Nenhum chunk pequeno recebido para expandir.');
}

return input.chunks.map((chunk) => ({
  json: {
    documento_id: input.documento_id,
    auth_user_id: input.auth_user_id,
    chunk_index: chunk.chunk_index,
    conteudo: chunk.conteudo,
    conteudo_hash: chunk.conteudo_hash,
    token_count: chunk.token_count
  }
}));

// ALTERACAO INDICE CONTEXTUAL
// Centraliza os dados de finalizacao para documento pequeno e grande.
// O node tambem informa que, apos finalizar status_indexacao=indexado,
// o fluxo deve gerar o indice contextual do documento.

function getJsonFromNode(name) {
  try {
    return $(name).first().json || {};
  } catch {
    return {};
  }
}

const input = $input.first().json || {};
const webhook = getJsonFromNode('Webhook').body || {};
const gerarChunks = getJsonFromNode('Gerar chunks');
const agruparChunks = getJsonFromNode('Agrupar chunks indexados');
const retornoIndexacaoLenta = getJsonFromNode('Indexar chunks pendentes documento grande');

const documentoId =
  input.documento_id ||
  retornoIndexacaoLenta.documento_id ||
  agruparChunks.documento_id ||
  gerarChunks.documento_id ||
  webhook.documento_id;

const authUserId =
  input.auth_user_id ||
  retornoIndexacaoLenta.auth_user_id ||
  agruparChunks.auth_user_id ||
  gerarChunks.auth_user_id ||
  webhook.auth_user_id;

const qtdChunks = Number(
  input.qtd_chunks ||
  retornoIndexacaoLenta.qtd_chunks ||
  agruparChunks.qtd_chunks ||
  gerarChunks.qtd_chunks ||
  0
);

const embeddingModel =
  input.embedding_model ||
  retornoIndexacaoLenta.embedding_model ||
  agruparChunks.embedding_model ||
  'text-embedding-3-small';

if (!documentoId) {
  throw new Error('documento_id ausente para finalizar indexacao.');
}

if (!authUserId) {
  throw new Error('auth_user_id ausente para finalizar indexacao.');
}

if (!qtdChunks || qtdChunks <= 0) {
  throw new Error('qtd_chunks invalido para finalizar indexacao.');
}

return [{
  json: {
    documento_id: documentoId,
    auth_user_id: authUserId,
    qtd_chunks: qtdChunks,
    embedding_model: embeddingModel,
    gerar_indice_contextual: true,
    limite_amostra_indice_contextual: Number(input.limite_amostra_indice_contextual || retornoIndexacaoLenta.limite_amostra_indice_contextual || 15)
  }
}];

// ALTERACAO INDICE CONTEXTUAL
// Monta o payload para gerar o resumo semantico do documento a partir da amostra.

const amostra = $json;
const chunks = Array.isArray(amostra.chunks_amostra) ? amostra.chunks_amostra : [];

if (!amostra.documento_id || !Array.isArray(chunks) || chunks.length === 0) {
  throw new Error('Amostra do documento ausente ou vazia para gerar indice contextual.');
}

const textoAmostra = chunks
  .map(chunk => '# Chunk ' + chunk.chunk_index + '\n' + String(chunk.conteudo || '').trim())
  .filter(Boolean)
  .join('\n\n---\n\n');

const body = {
  model: 'openai/gpt-4.1-mini',
  temperature: 0.1,
  response_format: { type: 'json_object' },
  messages: [
    {
      role: 'system',
      content: `You generate semantic document indexes for a corporate RAG system.

You will receive a sample from the beginning, middle, and end of a document already split into chunks.
Your task is to create a search summary that helps retrieve this document from natural user questions.

Return only valid JSON in this format:
{
  "titulo_detectado": "short string or null",
  "tipo_documento": "politica|contrato|manual|processo|faq|pitch|treinamento|outro",
  "resumo_busca": "objective text with 800 to 1600 characters, including important terms from the document",
  "assuntos": ["topic 1", "topic 2"],
  "entidades": {
    "pessoas": [],
    "empresas": [],
    "produtos": [],
    "areas": [],
    "datas": [],
    "valores": []
  }
}

Rules:
- Do not invent information that is not present in the sample.
- If the sample is inconclusive, say that in resumo_busca.
- The summary is for semantic search, not for final user presentation.
- Include natural synonyms only when clearly derived from the content.`.trim()
    },
    {
      role: 'user',
      content: `Document: ${amostra.documento_id}
Category: ${amostra.categoria_nome || amostra.categoria_id || 'no category'}
Total chunks: ${amostra.qtd_chunks || 0}

Chunk sample:

${textoAmostra}`.trim()
    }
  ]
};

return [{
  json: {
    documento_id: amostra.documento_id,
    cadastro_id: amostra.cadastro_id,
    categoria_id: amostra.categoria_id,
    categoria_nome: amostra.categoria_nome,
    qtd_chunks: amostra.qtd_chunks,
    embedding_model_documento: amostra.embedding_model,
    body_resumo: body
  }
}];

// ALTERACAO INDICE CONTEXTUAL
// Normaliza o JSON retornado pela IA e monta o texto que sera embedado.

const content = $json.choices?.[0]?.message?.content || '{}';

let parsed;
try {
  parsed = JSON.parse(String(content).replace(/```json/g, '').replace(/```/g, '').trim());
} catch (error) {
  throw new Error('Nao foi possivel interpretar o resumo semantico retornado pela IA: ' + error.message);
}

const documento = $('Montar payload resumo indice').item.json;
const finalizacao = $('Preparar finalizacao indexacao').item.json;

const tituloDetectado = parsed.titulo_detectado ? String(parsed.titulo_detectado).trim() : null;
const tipoDocumento = parsed.tipo_documento ? String(parsed.tipo_documento).trim().toLowerCase() : 'outro';
const resumoBusca = String(parsed.resumo_busca || '').trim();
const assuntos = Array.isArray(parsed.assuntos) ? parsed.assuntos.map(String).filter(Boolean) : [];
const entidades = parsed.entidades && typeof parsed.entidades === 'object' ? parsed.entidades : {};

if (!resumoBusca) {
  throw new Error('Resumo de busca vazio para indice contextual.');
}

const textoEmbedding = [
  tituloDetectado ? 'Titulo: ' + tituloDetectado : '',
  'Tipo: ' + tipoDocumento,
  assuntos.length ? 'Assuntos: ' + assuntos.join(', ') : '',
  'Resumo: ' + resumoBusca
].filter(Boolean).join('\n');

const tokenCount = Math.max(1, Math.ceil(textoEmbedding.length / 4));

return [{
  json: {
    documento_id: documento.documento_id,
    auth_user_id: finalizacao.auth_user_id,
    titulo_detectado: tituloDetectado,
    tipo_documento: tipoDocumento,
    resumo_busca: resumoBusca,
    assuntos_json: assuntos,
    entidades_json: entidades,
    texto_embedding: textoEmbedding,
    token_count: tokenCount,
    usage_resumo: $json.usage || null
  }
}];

// ALTERACAO OPENAI EMBEDDINGS
// A Edge Function gerar-embedding foi removida. Este node agora le o retorno direto da OpenAI.

const resumo = $('Normalizar resumo indice').item.json;
const embeddingResponse = $json;
const embedding = embeddingResponse?.data?.[0]?.embedding;

if (!Array.isArray(embedding)) {
  throw new Error('Embedding do resumo ausente.');
}

if (embedding.length !== 384) {
  throw new Error('Embedding do resumo com dimensao invalida: esperado 384, recebido ' + embedding.length + '.');
}

return {
  json: {
    documento_id: resumo.documento_id,
    auth_user_id: resumo.auth_user_id,
    titulo_detectado: resumo.titulo_detectado,
    tipo_documento: resumo.tipo_documento,
    resumo_busca: resumo.resumo_busca,
    assuntos_json: resumo.assuntos_json,
    entidades_json: resumo.entidades_json,
    embedding_resumo: embedding,
    embedding_model: 'text-embedding-3-small',
    token_count: resumo.token_count,
    usage_resumo: resumo.usage_resumo,
    usage_embedding: embeddingResponse?.usage || null
  }
};

